def win_rates(df):
    rates = {}
    for rep in sorted(df["Owner"].unique()):
        mine = df[df["Owner"] == rep]
        won = int((mine["Outcome"] == "won").sum())
        lost = int((mine["Outcome"] == "lost").sum())
        total = won + lost
        if total > 0:
            rates[rep] = round(won / total, 4)
        else:
            rates[rep] = 0.0  # or handle as appropriate for no wins/losses
    return rates
